    MangaController_getList: {
        parameters: {
            query: {
                sort_field?: "latest_chapter_at" | "created_at" | "publication_date" | "views" | "name" | "bangumi_rank" | "heat";
                sort_order?: "asc" | "desc";
                search?: string;
                serial_status?: components["schemas"]["MangaSerialStatus"];
                audience?: components["schemas"]["MangaAudience"];
                /** @description 按发源地区过滤 */
                region?: "jp" | "kr" | "cn" | "cjk" | "other";
                /** @description 排除的发源地区，null 发源地不受影响 */
                exclude_regions?: ("kr" | "western")[];
                /** @description 按开始发行年代过滤 */
                decade?: "2020s" | "2010s" | "2000s" | "earlier";
                /** @description 按连载杂志(producer id)过滤 */
                magazine_id?: number;
                /** @description 按标签名过滤 */
                tag?: string;
                /** @description Tag filter groups encoded as op.match.ids, e.g. include.and.1.2 or exclude.or.5.6. Groups are AND-combined. */
                tag_groups?: string[];
                /** @description 题材 genre key（见 MangaStatsDto.top_genres），多个之间 OR。例：romance,isekai */
                genre?: string[];
                /** @description 只看已开始发行的作品 */
                released?: boolean;
                /** @description 是否存在已成功匹配的漫画来源 */
                has_linked_source?: boolean;
                /** @description 只看站内可读(已采到章节)的作品。has_linked_source 只说明匹配上了源 */
                readable?: boolean;
                /** @description 只看热度不低于该值的作品 */
                min_heat?: number;
                page: number;
                page_size: number;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        items: components["schemas"]["MangaSummaryDto"][];
                        meta: components["schemas"]["PageMetaDto"];
                    };
                };
            };
        };
    };
